<script lang="ts">
 import Spooly from './Spooly.svelte';
 import SidebarToggle from "./SidebarToggle.svelte";
 import {workspaceRedirect} from './workspaceAccess';
 import EnquiryWorkspace from "./EnquiryWorkspace.svelte";
 import SampleWorkspace from "./SampleWorkspace.svelte";
 import MaterialWorkspace from "./MaterialWorkspace.svelte";
 import SignInForm from "./SignInForm.svelte";
 import {enter, workspaceMotion} from "./motion";
 import '../app.css';
 import '../dashboard.css';
 let {portal=''}:{portal?:string}=$props();
 import {onMount} from 'svelte';
 import {LayoutDashboard,ClipboardList,CalendarDays,PenTool,Scissors,Factory,PackageCheck,Truck,Warehouse,Users,Building2,ShieldCheck,Settings,Search,Plus,ArrowUpRight,ArrowRight,ChevronDown,LogOut,Download,RefreshCw,Menu,X,Activity,Boxes,ShoppingCart,Layers,Check,Clock,AlertCircle,SlidersHorizontal,LockKeyhole,LoaderCircle,FileCheck,Shirt} from '@lucide/svelte';
 import {api,fmt,day} from '$lib/api';import type {Dataset,Row,FormSpec,Field,Option} from '$lib/types';
 import FormDialog from '$lib/FormDialog.svelte';
 import OrderDrawer from '$lib/OrderDrawer.svelte';
 import Badge from '$lib/Badge.svelte';
 import DataTable from '$lib/DataTable.svelte';
 let blockedUser:Row|null=$state(null);let noAccess=$state(false);
 let enquiryDirty=$state(false);
 let data:Dataset|null=$state(null);let loading=$state(true);let error=$state('');let loginBusy=$state(false);let username=$state('');let password=$state('');let page=$state('Overview');let company=$state('');let search=$state('');let stageFilter=$state('');let form:FormSpec|null=$state(null);let selectedId:number|null=$state(null);let toast=$state('');let mobileNav=$state(false);let refreshing=$state(false);let local=$state(true);
 let selected=$derived.by(()=>data?.orders.find(o=>o.id===selectedId));
 const can=(g:string)=>g==='finish_or_pack'?!!data?.user.grants.some(v=>['finish','pack'].includes(v)):!!data?.user.grants.includes(g);
 let companies:Row[]=$derived.by(()=>data?.companies||[]);
 const inCompany=(r:Row)=>!company||String(r.company_id||r.id)===company;
 const filter=(list:Row[])=>list.filter(r=>(!company||String(r.company_id)===company)&&(!search||Object.values(r).some(v=>typeof v==='string'&&v.toLowerCase().includes(search.toLowerCase()))));
 let orders:Row[]=$derived.by(()=>filter(data?.orders||[]));
 let activeOrders=$derived(orders.filter(o=>!['Dispatched'].includes(o.stage)&&o.approval!=='Rejected'));
 let today=$state(new Date().toLocaleDateString('en-CA'));
 let overdue=$derived(activeOrders.filter(o=>o.due_date<today));
 let pending=$derived(orders.filter(o=>o.approval==='Pending'));
 let floor:Row[]=$derived.by(()=>(data?.lines||[]).filter(l=>!company||String(l.company_id)===company));
 let purchases:Row[]=$derived.by(()=>filter(data?.purchases||[]).map(p=>({...p,supplier:p.supplier_name||data?.suppliers.find(s=>s.id===p.supplier_id)?.name||'—',item:p.item_name||data?.inventory.find(i=>i.id===p.item_id)?.name||'—'})));
 let stock:Row[]=$derived.by(()=>filter(data?.inventory||[]));
 let lowStock=$derived(stock.filter(i=>i.stock_hundredths<i.reorder_hundredths));
 const options=(list:Row[],label='name'):Option[]=>list.map(r=>({value:r.id,label:r[label]}));
 const choices=(values:string[]):Option[]=>values.map(value=>({value,label:value}));
 const currentCompany=()=>Number(company||companies[0]?.id||0);
 const scoped=(list:Row[])=>list.filter(r=>r.company_id===currentCompany());
 function notify(message:string){toast=message;setTimeout(()=>toast='',4500);}
 async function refresh(strict=false){refreshing=true;try{data=await api('/data');error='';}catch(e){error=(e as Error).message;const session=await api('/session');if(session.user?.renewal_blocks?.length){blockedUser=session.user;data=null;}if(strict)throw e;}finally{refreshing=false;}}
 async function mutate(){await refresh(true);notify('Changes saved.');}
 onMount(()=>{const requested=new URL(location.href).searchParams.get('account');if(requested)username=requested;let stopped=false;const expired=()=>{data=null;blockedUser=null;noAccess=false;selectedId=null;error='Your session changed. Please sign in again.';};window.addEventListener('erp:session-expired',expired);(async()=>{try{const session=await api('/session');local=session.local;if(session.user&&requested&&session.user.username!==requested){await api('/logout',{});}else if(session.user){const redirect=workspaceRedirect(session.user,portal,'operations');if(redirect){window.location.replace(redirect+location.search);return;}if(session.user.renewal_blocks?.length){blockedUser=session.user;return;}if(!session.user.grants.includes('view_orders')){noAccess=true;return;}await refresh();company=String(data?.companies[0]?.id||'');if(data)page=local&&new URL(location.href).searchParams.get('view')==='test'?'Test dashboards':landingPage();}}catch(e){error=(e as Error).message;}finally{loading=false;}})();const timer=setInterval(()=>{if(data&&!refreshing&&!form&&!selectedId&&!enquiryDirty&&!stopped)refresh();},15000);return()=>{stopped=true;clearInterval(timer);window.removeEventListener('erp:session-expired',expired);};});
 async function signedIn(result:Row){const redirect=workspaceRedirect(result.user,portal,'operations');if(redirect){window.location.replace(redirect+location.search);return;}if(result.user.renewal_blocks?.length){blockedUser=result.user;return;}if(!result.user.grants.includes('view_orders')){noAccess=true;return;}await refresh();company=String(data?.companies[0]?.id||'');if(data)page=local&&new URL(location.href).searchParams.get('view')==='test'?'Test dashboards':landingPage();}
 async function logout(){try{await api('/logout',{});blockedUser=null;noAccess=false;data=null;selectedId=null;}catch(e){error=(e as Error).message;}}
 function navigate(next:string){if(enquiryDirty&&!window.confirm('Discard unsaved enquiry changes?'))return;enquiryDirty=false;if(next==='Export Documentation'){window.location.assign('/exports');return;}if(next==='User access'){window.location.assign('/admin/users');return;}page=next;search='';stageFilter='';mobileNav=false;}
 function openRecord(r:Row){selectedId=r.id;}
 function newForm(title:string,path:string,fields:Field[],description?:string){form={title,description,fields,submit:async v=>{await api(path,v);await mutate();}};}
 const companyField=():Field=>({key:'company_id',label:'Company',type:'select',value:currentCompany(),options:options(companies.filter(c=>c.status==='Approved'&&c.id===currentCompany())),hint:'Choose the company in the top bar before opening this form.'});
 function createOrder(){newForm('New buyer order','/orders',[companyField(),{key:'buyer_id',label:'Buyer / brand',type:'select',options:options(scoped(data?.buyers||[])),hint:'Buyer choices use the company selected in the top bar.'},{key:'po',label:'Buyer PO reference'},{key:'style',label:'Style / description'},{key:'product',label:'Product category',type:'select',options:choices(data?.products||[])},{key:'quantity',label:'Order quantity (pcs)',type:'number',min:1},{key:'due_date',label:'Ex-factory date',type:'date'},{key:'currency',label:'Currency',type:'select',value:'USD',options:choices(['USD','INR','EUR','GBP'])},{key:'unit_price',label:'Unit selling price',type:'number',min:0,step:'0.01',value:0},{key:'notes',label:'Order notes',type:'textarea',required:false}],'Create the PO, then send it through approval and production.');}
 function createSupplier(){newForm('Add supplier','/records/suppliers',[companyField(),{key:'name',label:'Supplier company'},{key:'category',label:'Category',type:'select',options:choices(data?.categories||[])},{key:'designation',label:'Sourcing relationship',type:'select',options:choices(['Nominated','Direct','Non-nominated'])},{key:'buyer_id',label:'Nominating buyer',type:'select',options:options(scoped(data?.buyers||[])),required:false,hint:'Required for nominated suppliers, including logistics.'},{key:'contact',label:'Contact details',required:false}]);}
 function createStock(){newForm('Add stock item','/records/inventory',[companyField(),{key:'sku',label:'Material SKU'},{key:'name',label:'Material description'},{key:'store',label:'Store',type:'select',options:choices(['Fabric','Trims'])},{key:'unit',label:'Unit',type:'select',options:choices(['metres','pieces','rolls','sets'])},{key:'reorder_level',label:'Reorder level',type:'number',step:'0.01',min:0,value:0}]);}
 function movement(item:Row){newForm('Stock movement','/inventory/'+item.id,[{key:'kind',label:'Movement',type:'select',options:choices(['Receipt','Issue'])},{key:'quantity',label:`Quantity (${item.unit})`,type:'number',step:'0.01',min:0.01},{key:'order_id',label:'Buyer PO',type:'select',options:options((data?.orders||[]).filter(o=>o.company_id===item.company_id&&o.approval==='Approved'),'po'),required:false,hint:'Required when issuing stock to production.'},{key:'reference',label:'GRN / issue reference'}],item.name+' · Available: '+fmt(item.stock_hundredths/100)+' '+item.unit);}
 function createPurchase(){newForm('New supplier purchase','/records/purchases',[companyField(),{key:'reference',label:'Purchase reference'},{key:'supplier_id',label:'Supplier',type:'select',options:options(scoped(data?.suppliers||[]))},{key:'item_id',label:'Material',type:'select',options:options(scoped(data?.inventory||[]))},{key:'order_id',label:'Buyer PO allocation',type:'select',options:options(scoped(data?.orders||[]),'po'),required:false},{key:'quantity',label:'Purchase quantity',type:'number',step:'0.01',min:0.01},{key:'unit_cost',label:'Unit cost (company currency)',type:'number',step:'0.01',min:0},{key:'due_date',label:'Expected delivery',type:'date'}]);}
 function reviewPurchase(p:Row){const actions=p.status==='Pending'&&can('approve')?['approve','reject']:p.status==='Approved'&&can('inventory')?['receive']:[];if(!actions.length){notify('No action available for your role at this stage.');return;}newForm(p.reference,'/records/purchases/'+p.id,[{key:'action',label:'Action',type:'select',options:actions.map(v=>({value:v,label:v==='receive'?'Receive full quantity into stock':v==='approve'?'Approve purchase':'Reject purchase'}))}],`${p.supplier} · ${fmt(p.quantity_hundredths/100)} units · ${p.status}`);}
 function createCompany(){newForm('Set up company','/records/companies',[{key:'name',label:'Company name'},{key:'kind',label:'Company type',type:'select',value:'Self',options:choices(['Self','Group','Sub company'])}],'New companies require MD approval before orders can be entered.');}
 async function approveCompany(c:Row){try{await api('/records/companies/'+c.id,{action:'approve'});await mutate();}catch(e){notify((e as Error).message);}}
 function createMaster(kind:string){const fields:Field[]=[companyField(),{key:'name',label:kind==='teams'?'Team name':kind==='buyers'?'Buyer / brand name':'Line name'}];if(kind==='buyers')fields.push({key:'team_id',label:'Assigned team',type:'select',options:options(scoped(data?.teams||[]))});if(kind==='lines')fields.push({key:'capacity',label:'Daily capacity (pcs)',type:'number',min:1,value:500});newForm('Add '+(kind==='teams'?'team':kind==='buyers'?'buyer':'sewing line'),'/records/'+kind,fields);}
 function userForm(target?:Row){const fields:Field[]=[];if(!target)fields.push({key:'name',label:'Full name'},{key:'username',label:'Username'},{key:'password',label:'Initial password',type:'password',hint:'12–128 characters. Share securely with the user.'});fields.push({key:'role',label:'Department role',type:'select',options:choices(data?.roles||[]),value:target?.role},{key:'scope',label:'Order visibility',type:'select',options:choices(['company','team','line','po']),value:target?.scope||'team'},{key:'companies',label:'Allowed companies',type:'multiselect',options:options(companies),value:target?.companies||[currentCompany()],hint:'Tick every company this user can access.'},{key:'teams',label:'Teams (for team scope)',type:'multiselect',options:options(data?.teams||[]),required:false,value:target?.teams||[]},{key:'lines',label:'Sewing lines (for line scope)',type:'multiselect',options:(data?.lines||[]).map(l=>({value:l.id,label:(companies.find(c=>c.id===l.company_id)?.name||'')+' · '+l.name})),required:false,value:target?.lines||[]},{key:'orders',label:'Assigned POs (for PO scope)',type:'multiselect',options:options(data?.orders||[],'po'),required:false,value:target?.orders||[]},{key:'finishing_units',label:'Finishing units (for finishing role)',type:'multiselect',options:choices(data?.products||[]),required:false,value:target?.finishing_units||[]});fields.push({key:'permissions',label:'Allowed actions',type:'multiselect',value:target?(target.custom_permissions?target.permissions:data?.role_grants[target.role]||[]):[],required:false,hint:'Tick the actions this person may perform. Unticked actions are blocked by the API.'});form={title:target?'Edit user access':'Add team member',description:'Choose the department, then tick companies, assignments and allowed actions.',fields,permissionsByRole:data?.role_grants,submit:async v=>{await api(target?'/users/'+target.id:'/users',v);await mutate();}};}
 async function toggleUser(u:Row){try{await api('/users/'+u.id,{active:!u.active});await mutate();}catch(e){notify((e as Error).message);}}

 const orderColumns=[{key:'po',label:'Buyer PO'},{key:'buyer',label:'Buyer / brand'},{key:'style',label:'Style'},{key:'quantity',label:'Quantity',format:'number'},{key:'stage',label:'Stage',format:'badge'},{key:'line',label:'Line'},{key:'due_date',label:'Ex-factory',format:'date'}];
 const groups=[{label:'WORKSPACE',items:[{name:'Overview',icon:LayoutDashboard},{name:'Buyer orders',icon:ClipboardList},{name:'Enquiries & costing',icon:FileCheck,grant:'enquiries'},{name:'Export Documentation',icon:Truck,grant:'export_view'},{name:'Planning & T&A',icon:CalendarDays,grant:'plan'}]},{label:'MANUFACTURING',items:[{name:'Development & CAD',icon:PenTool,grant:'develop'},{name:'Sampling',icon:Shirt,grant:'sample_indents'},{name:'Cutting',icon:Scissors,grant:'cut'},{name:'Sewing floor',icon:Factory,grant:'sew'},{name:'Finishing & packing',icon:PackageCheck,grant:'finish_or_pack'},{name:'Quality control',icon:ShieldCheck,grant:'quality'},{name:'Warehouse & dispatch',icon:Truck,grant:'warehouse'}]},{label:'MATERIALS',items:[{name:'Materials & samples',icon:Layers,grant:'material_view'},{name:'Suppliers',icon:Building2,grant:'suppliers'},{name:'Purchases',icon:ShoppingCart,grant:'purchases'},{name:'Inventory & stores',icon:Boxes,grant:'inventory'}]},{label:'MANAGEMENT',items:[{name:'Approvals',icon:FileCheck,grant:'approve'},{name:'Teams & buyers',icon:Settings,grant:'companies'},{name:'User access',icon:Users,grant:'users'},{name:'Reports & audit',icon:Activity,grant:'audit'}]}];
 const landing:Record<string,string>={MD:'Overview',CEO:'Overview',Finance:'Approvals',Marketing:'Buyer orders',Planning:'Planning & T&A',Development:'Development & CAD',Sampling:'Sampling',Sourcing:'Purchases',Stores:'Inventory & stores',Cutting:'Cutting',Production:'Sewing floor',Finishing:'Finishing & packing',Quality:'Quality control',Warehouse:'Warehouse & dispatch'};
 function landingPage(){const next=landing[data?.user.role||'']||'Overview';const item=groups.flatMap(g=>g.items).find(i=>i.name===next);return item&&'grant' in item&&!can(String(item.grant))?'Overview':next;}
 const testAccounts=[['admin','MD / Administrator','All demo companies and setup'],['ceo','CEO','Company operations and oversight'],['finance','Finance','Approvals and invoice references'],['merchant.a','Merchandiser · Team A','Only Team A buyer orders'],['merchant.b','Merchandiser · Team B','Only Team B buyer orders'],['planning','Planning','Allocate lines and send orders to CAD'],['cad','Development & CAD','Style and pattern approvals'],['sampling','Sampling','Sample approvals and cutting handoff'],['sourcing','Sourcing','Suppliers and material purchases'],['stores','Stores','Fabric and trims receipts / issues'],['cutting','Cutting','Cutting output and sewing handoff'],['pm.lines1-6','Production · Lines 1–6','Only orders allocated to lines 1–6'],['pm.lines7-20','Production · Lines 7–20','Only orders allocated to lines 7–20'],['finishing','Finishing manager','All product finishing units'],['finishing.suits','Assigned Suits POs','Only assigned Suits purchase orders'],['quality','Quality inspector','Inspect and pass / hold production'],['warehouse','Warehouse & logistics','Invoiced POs and dispatch']];
 const subtitles:Record<string,string>={'Test dashboards':'Sign in as a department user to follow the same order across its workflow.','Enquiries & costing':'From the buyer enquiry to an approved booking and production POs.','Overview':'Your factory, at a glance.','Buyer orders':'Follow every PO from development to dispatch.','Planning & T&A':'Keep allocations and delivery milestones on track.','Development & CAD':'Style development, patterns and revisions.','Sampling':'Proto, fit and pre-production sample approvals.','Cutting':'Table allocation, markers and cutting output.','Sewing floor':'Live order progress across your assigned lines.','Finishing & packing':'Product-specific finishing, quality and final packing.','Quality control':'Inspection results across the production process.','Warehouse & dispatch':'Packed goods, invoice references and shipment readiness.','Materials & samples':'Fabric, trims, master lists and supplier ratings.','Suppliers':'Company suppliers, sourcing relationships and buyer nominations.','Purchases':'Approve material purchases and receive them into stock.','Inventory & stores':'Separate fabric and trims stores with a movement ledger.','Approvals':'Orders and purchases waiting for your review.','Teams & buyers':'Companies, buyer teams and production resources.','User access':'Department roles and precise order visibility.','Reports & audit':'Export operational data and review recorded changes.'};
</script>

<svelte:head><title>Euro Suits · {data?page:'Sign in'}</title><meta name="description" content="Euro Suits manufacturing operations workspace"/></svelte:head>
{#if loading}<div class="loading-screen"><img src="/logo.png" alt="Euro Suits"/><LoaderCircle size={25} class="spin"/><p>Opening your workspace…</p></div>
{:else if blockedUser||noAccess}<main class="login-panel"><section class="panel company-section"><h1>{blockedUser?'Renewal action required':'No features assigned'}</h1><p>{blockedUser?'Your dashboard is locked because a document is at least 30 days overdue. Contact Finance to renew it and MD or Super Admin for approval.':'Admin must assign permissions to this account.'}</p>{#each blockedUser?.renewal_blocks||[] as b}<p><strong>{b.legal_name}</strong> · {b.label} · {b.expires_on}</p>{/each}<button class="button primary" onclick={()=>window.location.reload()}>Check access again</button><button class="button secondary" onclick={logout}>Sign out</button></section></main>
{:else if !data}
 <main class="login-layout"><section class="login-brand"><div class="login-brand-name"><img src="/logo.png" alt="Euro Suits company logo"/><span>EURO SUITS</span></div><div><p class="eyebrow">MANUFACTURING OPERATIONS</p><h1>Every order.<br/>Every detail.<br/><span>One workspace.</span></h1><p>From the first pattern to the final dispatch.</p></div><small>EURO SUITS · EURO TRS MFG</small></section><section class="login-panel"><div class="login-form-wrap" use:enter><span class="login-symbol"><LockKeyhole size={24}/></span><h2>{portal?portal.charAt(0).toUpperCase()+portal.slice(1)+' sign in':'Welcome back'}</h2><p class="muted">Sign in to your operations workspace.</p><SignInForm {portal} initialUsername={username} onauthenticated={signedIn}/>{#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if local}<div class="local-note"><span class="demo-dot"></span>Local testing environment<small>Use the credentials in LOCAL-ACCESS.txt.</small></div>{/if}<p class="login-help">Need access? Contact your company administrator.</p></div></section></main>
{:else}
 <div class="app-layout erp-workspace"><a class="workspace-skip" href="#workspace-content">Skip to workspace</a>
 <aside class:mobile-open={mobileNav} class="sidebar"><div class="brand"><img src="/logo.png" alt="Euro Suits logo"/><div><strong>EURO SUITS</strong><span>OPERATIONS</span></div><button class="icon-button mobile-close" aria-label="Close navigation" onclick={()=>mobileNav=false}><X size={20}/></button></div>
 <div class="workspace-label"><span class="workspace-monogram">ES</span><div><strong>Manufacturing workspace</strong></div></div>
 <nav aria-label="Main navigation">{#if ['Super Admin','MD','Finance Head'].includes(data.user.role)}<a class="button secondary" href={'/'+(data.user.role==='Super Admin'?'admin':data.user.role==='MD'?'md':'finance')}>Company Setup & access</a>{/if}{#each groups as group}{#if group.items.some(item=>!('grant' in item)||can(String(item.grant||'')))}<div class="nav-group"><p>{group.label}</p>{#each group.items as item}{#if !('grant' in item)||can(String(item.grant||''))}<button class:active={page===item.name} aria-current={page===item.name?'page':undefined} onclick={()=>navigate(item.name)}><item.icon size={18}/><span>{item.name}</span>{#if item.name==='Approvals'&&pending.length}<b>{pending.length}</b>{/if}</button>{/if}{/each}</div>{/if}{/each}</nav>
 <div class="sidebar-bottom">{#if local}<div class="demo-label"><span></span>Local workspace</div>{/if}<div class="profile-button" title="Account details are managed by the developer"><span class="avatar">{data.user.name.split(' ').map(s=>s[0]).slice(0,2).join('')}</span><span><strong>{data.user.name}</strong><small>{data.user.role} · {data.user.scope} access</small></span></div><button class="logout" onclick={logout}><LogOut size={15}/>Sign out</button></div>
 </aside>
 <div class="main-shell"><header class="topbar"><div class="breadcrumb"><SidebarToggle/><button class="icon-button mobile-menu" aria-label="Open navigation" onclick={()=>mobileNav=true}><Menu size={21}/></button><span>Workspace</span><span class="slash">/</span><strong>{page}</strong></div><div class="topbar-actions">{#if companies.length>1}<label class="company-switch"><Building2 size={15}/><select aria-label="Company" disabled={enquiryDirty} bind:value={company}><option value="">All companies</option>{#each companies as c}<option value={String(c.id)}>{c.name}</option>{/each}</select></label>{/if}<button class="icon-button" aria-label="Refresh workspace" onclick={()=>refresh()} disabled={refreshing}><RefreshCw size={17} class={refreshing?'spin':''}/></button><span class="top-avatar" title="Account details are managed by the developer">{data.user.name[0]}</span></div></header>
 <main id="workspace-content" class="workspace-main" tabindex="-1" use:workspaceMotion={page}><div class="page-heading" use:enter={page}><div><p class="eyebrow">{page==='Overview'?'OPERATIONS WORKSPACE':'WORKSPACE'}</p><h1>{page}</h1><p>{subtitles[page]}</p></div><div class="heading-actions">{#if page==='Overview'||page==='Buyer orders'}<a class="button secondary" href={'/api/orders/export'+(company?'?company='+company:'')}><Download size={16}/>Export</a>{#if can('orders')}<button class="button primary" onclick={createOrder}><Plus size={17}/>New order</button>{/if}{:else if page==='Suppliers'&&can('suppliers')}<button class="button primary" onclick={createSupplier}><Plus size={17}/>Add supplier</button>{:else if page==='Purchases'&&can('purchases')}<button class="button primary" onclick={createPurchase}><Plus size={17}/>New purchase</button>{:else if page==='Inventory & stores'&&can('inventory')}<button class="button primary" onclick={createStock}><Plus size={17}/>Add stock item</button>{:else if page==='Teams & buyers'&&can('companies')}<a class="button secondary" href="/admin">Company register</a>{:else if page==='User access'}<button class="button primary" onclick={()=>userForm()}><Plus size={17}/>Add team member</button>{/if}</div></div>
 {#if error}<div class="form-error" role="alert">{error}<button class="text-button" onclick={()=>refresh()}>Retry</button></div>{/if}
 {#if page==='Test dashboards'&&local}
 <div class="test-intro"><ShieldCheck size={22}/><div><h2>Test real role permissions</h2><p>Choose an account below, then enter the local test password. Switching accounts signs out your current browser session. Use a separate browser profile for simultaneous users.</p></div></div><div class="test-account-grid">{#each testAccounts as account}<a class="test-account-card" data-sveltekit-reload href={'/?account='+encodeURIComponent(account[0])}><div><Users size={20}/><ArrowUpRight size={16}/></div><h3>{account[1]}</h3><code>{account[0]}</code><p>{account[2]}</p><span>Open sign-in <ArrowRight size={14}/></span></a>{/each}</div>
 {:else if page==='Overview'}
  <div class="overview-context"><span><span class="live-dot"></span>Operational snapshot</span><span>{new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span>{#if local}<span class="sample-label">Illustrative demo data</span>{/if}</div>
  <div class="metric-grid"><div class="metric"><div><span>Active orders</span><ClipboardList size={19}/></div><strong>{fmt(activeOrders.length)}</strong><small>{fmt(activeOrders.reduce((n,o)=>n+o.quantity,0))} pieces in the order book</small></div><div class="metric"><div><span>In production</span><Factory size={19}/></div><strong>{fmt(activeOrders.filter(o=>['Cutting','Sewing','Finishing'].includes(o.stage)).length)}</strong><small>Across cutting, sewing & finishing</small></div><div class="metric"><div><span>Ready for dispatch</span><PackageCheck size={19}/></div><strong>{fmt(orders.filter(o=>o.stage==='Invoiced').length)}</strong><small>{orders.filter(o=>o.stage==='Warehouse').length} packed POs awaiting invoice</small></div><div class="metric attention-metric"><div><span>Needs attention</span><AlertCircle size={19}/></div><strong>{fmt(overdue.length+pending.length)}</strong><small>{overdue.length} overdue · {pending.length} awaiting approval</small></div></div>
  <div class="overview-columns"><section class="panel pipeline-panel"><div class="panel-header"><div><h2>Production pipeline</h2><p>Active orders by their current stage</p></div><span class="subtle-chip">{activeOrders.length} orders</span></div><div class="pipeline">{#each ['Planning','Development','Sampling','Cutting','Sewing','Finishing','Packing','Warehouse'] as stage,i}{@const count=activeOrders.filter(o=>o.stage===stage).length}<button class="pipeline-column" onclick={()=>{navigate('Buyer orders');stageFilter=stage;}}><span class="pipeline-count">{count}</span><div class="pipeline-track"><div style:height={(count?Math.max(14,count/Math.max(1,...data.stages.map(s=>activeOrders.filter(o=>o.stage===s).length))*100):3)+'%'} style:background={['#cbd8e5','#b7cbdd','#93b9d2','#77abbf','#20918c','#37a6a0','#71c1b8','#acdcd4'][i]}></div></div><span>{stage}</span></button>{/each}</div><div class="pipeline-footer"><span><Layers size={15}/> From style creation to finished goods</span><button class="text-button" onclick={()=>navigate('Planning & T&A')}>View planning <ArrowRight size={14}/></button></div></section>
  <section class="panel attention-panel"><div class="panel-header"><div><h2>On your radar</h2><p>Items that need a closer look</p></div><Clock size={19}/></div><div class="attention-list">{#each overdue.slice(0,2) as o}<button onclick={()=>openRecord(o)}><span class="attention-icon red"><Clock size={17}/></span><div><strong>{o.po} is past ex-factory</strong><small>{o.buyer} · {day(o.due_date)}</small></div><ArrowUpRight size={16}/></button>{/each}{#each pending.slice(0,2) as o}<button onclick={()=>openRecord(o)}><span class="attention-icon amber"><FileCheck size={17}/></span><div><strong>PO approval required</strong><small>{o.po} · {o.buyer}</small></div><ArrowUpRight size={16}/></button>{/each}{#if lowStock.length}<button onclick={()=>navigate('Inventory & stores')}><span class="attention-icon blue"><Boxes size={17}/></span><div><strong>{lowStock.length} materials below reorder level</strong><small>Review fabric and trims availability</small></div><ArrowUpRight size={16}/></button>{/if}{#if !overdue.length&&!pending.length&&!lowStock.length}<div class="empty"><Check size={28}/><p>No pending items in your current scope.</p></div>{/if}</div></section></div>
  <section class="panel"><div class="panel-header"><div><h2>Upcoming deliveries</h2><p>Priority orders in your current workspace</p></div><button class="text-button" onclick={()=>navigate('Buyer orders')}>All orders <ArrowRight size={15}/></button></div><DataTable rows={activeOrders.slice(0,5)} columns={orderColumns.filter(c=>c.key!=='line')} onopen={openRecord}/></section>
  <section class="floor-section"><div class="section-title"><div><h2>Sewing floor</h2><p class="muted">Current sewing assignments</p></div><button class="text-button" onclick={()=>navigate('Sewing floor')}>View all {floor.length} lines <ArrowRight size={15}/></button></div><div class="line-grid compact">{#each floor.filter(l=>orders.some(o=>o.line_id===l.id&&o.stage==='Sewing')).slice(0,4) as line}{@const o=orders.find(o=>o.line_id===line.id&&o.stage==='Sewing')}<button class="line-card" onclick={()=>o&&openRecord(o)}><div><strong>{line.name}</strong><span class="running-tag">Sewing</span></div><p>{o?.style}</p><small>{o?.po} · {o?.buyer}</small><progress max={o?.quantity||1} value={o?.totals?.Sewing||0}></progress><footer><span>{fmt(o?.totals?.Sewing)} / {fmt(o?.quantity)} pcs</span><strong>{Math.round((o?.totals?.Sewing||0)/(o?.quantity||1)*100)}%</strong></footer></button>{:else}<p class="muted">No active sewing assignments.</p>{/each}</div></section>
 {:else if page==='Enquiries & costing'}{#key company}<EnquiryWorkspace {companies} {company} bind:dirty={enquiryDirty}/>{/key}
 {:else if page==='Materials & samples'}{#key company}<MaterialWorkspace companyID={Number(company)}/>{/key}
 {:else if page==='Buyer orders'||page==='Cutting'||page==='Finishing & packing'||page==='Warehouse & dispatch'}
  {@const allowedStages=page==='Cutting'?['Cutting']:page==='Finishing & packing'?['Finishing','Packing']:page==='Warehouse & dispatch'?['Warehouse','Invoiced','Dispatched']:data.stages}
  <section class="panel"><div class="table-toolbar"><div class="filter-tabs"><button class:active={!stageFilter} onclick={()=>stageFilter=''}>All <span>{orders.filter(o=>allowedStages.includes(o.stage)).length}</span></button>{#each (page==='Buyer orders'?['Development','Sewing','Finishing','Warehouse']:allowedStages) as s}<button class:active={stageFilter===s} onclick={()=>stageFilter=s}>{page==='Warehouse & dispatch'?(s==='Warehouse'?'Awaiting invoice':s==='Invoiced'?'Awaiting dispatch':'Dispatched'):s}</button>{/each}</div><label class="search-box"><Search size={16}/><input aria-label="Search orders" placeholder="Search PO, buyer or style…" bind:value={search}/></label></div><DataTable rows={orders.filter(o=>allowedStages.includes(o.stage)&&(!stageFilter||o.stage===stageFilter))} columns={page==='Finishing & packing'?[...orderColumns.slice(0,5),{key:'finishing_unit',label:'Finishing unit'},{key:'sub_line',label:'Sub-line'}]:orderColumns} onopen={openRecord}/><div class="table-footer">{orders.filter(o=>allowedStages.includes(o.stage)&&(!stageFilter||o.stage===stageFilter)).length} orders · Select a PO to view details and take action.</div></section>
 {:else if page==='Sewing floor'}
  <div class="floor-summary"><span><strong>{floor.filter(l=>orders.some(o=>o.line_id===l.id&&o.stage==='Sewing')).length}</strong> active sewing lines</span><span><strong>{floor.length}</strong> visible lines</span><span><strong>{data.user.scope==='line'?'Assigned lines':'Company lines'}</strong> access scope</span></div><div class="line-grid">{#each floor as line}{@const assigned=orders.filter(o=>o.line_id===line.id&&o.stage==='Sewing')}<div class="line-card"><div><strong>{line.name}</strong><span class:idle={!assigned.length} class="running-tag">{assigned.length?'Sewing':'Available'}</span></div>{#each assigned as o}<button class="line-order" onclick={()=>openRecord(o)}><p>{o.style}</p><small>{o.po} · {o.buyer}</small><progress max={o.quantity} value={o.totals?.Sewing||0}></progress><footer><span>{fmt(o.totals?.Sewing)} / {fmt(o.quantity)} pcs</span><ArrowUpRight size={15}/></footer></button>{:else}<div class="idle-line"><Factory size={25}/><span>No order currently sewing</span></div>{/each}<div class="line-capacity">Planned capacity: {fmt(line.capacity)} pcs / day</div></div>{/each}</div>
 {:else if page==='Planning & T&A'}
  <section class="panel"><div class="panel-header"><div><h2>Order planning board</h2><p>Open a PO to allocate lines, tables and finishing sub-lines.</p></div><CalendarDays size={20}/></div><DataTable rows={orders.filter(o=>o.stage==='Planning')} columns={[{key:'po',label:'Buyer PO'},{key:'style',label:'Style'},{key:'stage',label:'Stage',format:'badge'},{key:'line',label:'Sewing line'},{key:'cutting_table',label:'Cutting table'},{key:'marker',label:'Marker'},{key:'due_date',label:'Ex-factory',format:'date'}]} onopen={openRecord}/></section><section class="panel spaced"><div class="panel-header"><h2>Open milestones</h2><span class="subtle-chip">Time & action</span></div><DataTable rows={orders.flatMap(o=>(o.milestones||[]).filter((m:Row)=>!m.done).map((m:Row)=>({...m,po:o.po,style:o.style,order_id:o.id}))).sort((a,b)=>a.due_date.localeCompare(b.due_date))} columns={[{key:'title',label:'Milestone'},{key:'po',label:'Buyer PO'},{key:'style',label:'Style'},{key:'due_date',label:'Due date',format:'date'}]} onopen={m=>selectedId=m.order_id}/></section>
 {:else if page==='Development & CAD'||page==='Sampling'}
 {#if page==='Sampling'}<SampleWorkspace {companies} {company} orders={data.orders}/>{/if}
  <section class="panel"><div class="panel-header"><div><h2>{page==='Sampling'?'Sample register':'Development register'}</h2><p>Open the associated order to add records, documents or approvals.</p></div></div><DataTable rows={data.work_items.filter(w=>orders.some(o=>o.id===w.order_id&&o.stage===(page==='Sampling'?'Sampling':'Development'))&&w.kind.includes('sample')===(page==='Sampling')).map(w=>({...w,po:orders.find(o=>o.id===w.order_id)?.po}))} columns={[{key:'title',label:'Style / record'},{key:'po',label:'Buyer PO'},{key:'kind',label:'Type'},{key:'status',label:'Status',format:'badge'},{key:'notes',label:'Revision notes'}]} onopen={w=>{selectedId=w.order_id;}}/></section>
 {:else if page==='Quality control'}
  <div class="mini-metrics"><div><span>Inspections</span><strong>{data.quality.filter(q=>orders.some(o=>o.id===q.order_id)).length}</strong></div><div><span>Held or rework results</span><strong>{data.quality.filter(q=>orders.some(o=>o.id===q.order_id)&&q.result!=='Pass').length}</strong></div></div><section class="panel"><div class="panel-header"><h2>Inspection register</h2><button class="text-button" onclick={()=>navigate('Buyer orders')}>Open an order to inspect <ArrowRight size={15}/></button></div><DataTable rows={data.quality.filter(q=>orders.some(o=>o.id===q.order_id)).toReversed().map(q=>({...q,po:orders.find(o=>o.id===q.order_id)?.po}))} columns={[{key:'po',label:'Buyer PO'},{key:'stage',label:'Stage'},{key:'inspected',label:'Inspected',format:'number'},{key:'defects',label:'Defects',format:'number'},{key:'result',label:'Result',format:'badge'},{key:'created_at',label:'Date',format:'date'}]} onopen={q=>selectedId=q.order_id}/></section>
 {:else if page==='Suppliers'}
  <section class="panel"><div class="table-toolbar"><span>{filter(data.suppliers).length} suppliers</span><label class="search-box"><Search size={16}/><input aria-label="Search suppliers" placeholder="Search suppliers…" bind:value={search}/></label></div><DataTable rows={filter(data.suppliers).map(s=>({...s,buyer:data?.buyers.find(b=>b.id===s.buyer_id)?.name||'—'}))} columns={[{key:'name',label:'Supplier company'},{key:'category',label:'Category'},{key:'designation',label:'Relationship',format:'badge'},{key:'buyer',label:'Nominating buyer'},{key:'contact',label:'Contact'}]}/></section>
 {:else if page==='Purchases'}
  <section class="panel"><div class="panel-header"><h2>Supplier purchase orders</h2><span class="subtle-chip">{purchases.filter(p=>p.status==='Pending').length} pending approval</span></div><DataTable rows={purchases} columns={[{key:'reference',label:'Purchase reference'},{key:'supplier',label:'Supplier'},{key:'item',label:'Material'},{key:'quantity_hundredths',label:'Quantity',format:'hundredths'},{key:'status',label:'Status',format:'badge'},{key:'due_date',label:'Expected',format:'date'}]} onopen={reviewPurchase}/></section>
 {:else if page==='Inventory & stores'}
  <div class="mini-metrics"><div><span>Fabric materials</span><strong>{stock.filter(i=>i.store==='Fabric').length}</strong></div><div><span>Trims materials</span><strong>{stock.filter(i=>i.store==='Trims').length}</strong></div><div><span>Below reorder level</span><strong>{lowStock.length}</strong></div></div><section class="panel"><div class="table-toolbar"><div class="filter-tabs">{#each ['','Fabric','Trims'] as s}<button class:active={stageFilter===s} onclick={()=>stageFilter=s}>{s||'All stores'}</button>{/each}</div><label class="search-box"><Search size={16}/><input aria-label="Search inventory" placeholder="Search SKU or material…" bind:value={search}/></label></div><DataTable rows={stock.filter(i=>!stageFilter||i.store===stageFilter).map(i=>({...i,availability:i.stock_hundredths<i.reorder_hundredths?'Reorder':'In stock'}))} columns={[{key:'sku',label:'Material SKU'},{key:'name',label:'Description'},{key:'store',label:'Store'},{key:'stock_hundredths',label:'On hand',format:'hundredths'},{key:'unit',label:'Unit'},{key:'reorder_hundredths',label:'Reorder level',format:'hundredths'},{key:'availability',label:'Availability',format:'badge'}]} onopen={movement}/><div class="table-footer">Select a material to record a receipt or issue to a buyer PO.</div></section>
 {:else if page==='Approvals'}
  <section class="panel"><div class="panel-header"><h2>Buyer orders awaiting approval</h2><span class="subtle-chip">{pending.length} pending</span></div><DataTable rows={pending} columns={orderColumns} onopen={openRecord}/></section><section class="panel spaced"><div class="panel-header"><h2>Supplier purchases awaiting approval</h2></div><DataTable rows={purchases.filter(p=>p.status==='Pending')} columns={[{key:'reference',label:'Reference'},{key:'supplier',label:'Supplier'},{key:'item',label:'Material'},{key:'quantity_hundredths',label:'Quantity',format:'hundredths'},{key:'due_date',label:'Expected',format:'date'}]} onopen={reviewPurchase}/></section>
 {:else if page==='Teams & buyers'}
  <div class="company-grid">{#each companies as c}<section class="panel company-card"><Building2 size={27}/><h2>{c.name}</h2><p>{c.kind} company</p><Badge value={c.status}/></section>{/each}</div>
  {#if can('users')}{#each [{kind:'teams',label:'Buyer teams',list:data.teams},{kind:'buyers',label:'Buyers & brands',list:data.buyers},{kind:'lines',label:'Sewing lines',list:data.lines}] as master}<section class="panel spaced"><div class="panel-header"><h2>{master.label}</h2><button class="text-button" onclick={()=>createMaster(master.kind)}><Plus size={16}/>Add</button></div><DataTable rows={scoped(master.list)} columns={[{key:'name',label:'Name'},...(master.kind==='lines'?[{key:'capacity',label:'Daily capacity (pcs)',format:'number'}]:[{key:'company_id',label:'Company ID'}])]}/></section>{/each}{/if}
 {:else if page==='User access'}
  <section class="panel"><div class="panel-header"><div><h2>Team directory</h2><p>Role controls actions. Scope controls which orders the user can access.</p></div><ShieldCheck size={20}/></div><div class="table-wrap"><table><thead><tr><th>Team member</th><th>Role</th><th>Order scope</th><th>Assignments</th><th>Status</th><th>Manage</th></tr></thead><tbody>{#each data.users as u}<tr><td><strong>{u.name}</strong><small class="block">{u.username}</small></td><td>{u.role}</td><td><Badge value={u.scope}/></td><td>{u.companies.length} companies{#if u.scope==='line'} · {u.lines.length} lines{:else if u.scope==='team'} · {u.teams.length} teams{:else if u.scope==='po'} · {u.orders.length} POs{/if}</td><td><Badge value={u.active?'Active':'Disabled'}/></td><td>{#if u.id!==data.user.id}<div class="row-actions"><button class="text-button" onclick={()=>userForm(u)}>Edit access</button><button class="text-button" onclick={()=>toggleUser(u)}>{u.active?'Disable':'Enable'}</button></div>{:else}<span class="muted">Your account</span>{/if}</td></tr>{/each}</tbody></table></div></section>
 {:else if page==='Reports & audit'}
  <section class="export-card"><div><FileCheck size={28}/><div><h2>Order status report</h2><p>Download the orders visible to your account and selected company.</p></div></div><a class="button primary" href={'/api/orders/export'+(company?'?company='+company:'')}><Download size={17}/>Export CSV</a></section><section class="panel spaced"><div class="panel-header"><h2>Activity & audit trail</h2><span class="subtle-chip">Latest 100 events</span></div><DataTable rows={filter(data.audit)} columns={[{key:'action',label:'Action'},{key:'detail',label:'Details'},{key:'actor',label:'User'},{key:'entity',label:'Record type'},{key:'created_at',label:'Date',format:'date'}]}/></section>
 {/if}
 <footer class="workspace-footer"><span>EURO SUITS OPERATIONS</span><span>{data.user.role} access</span></footer>
 </main></div></div>
 {#if selected}<OrderDrawer order={selected} {data} onclose={()=>selectedId=null} onform={s=>form=s} onmutate={mutate}/>{/if}
{/if}
{#if form}<FormDialog spec={form} onclose={()=>form=null}/>{/if}
{#if toast}<div class="toast" role="status"><Check size={18}/>{toast}</div>{/if}
{#if !loading && data && !blockedUser && !noAccess}
 <Spooly userId={data.user.id} role={data.user.role} {portal} {page}/>
{/if}
